import React from 'react';
import { motion } from 'framer-motion';
import './Skills.css';

const Skills = () => {
  const skillsData = {
    frontend: [
      { icon: 'fab fa-html5', name: 'HTML5', progress: '90%' },
      { icon: 'fab fa-css3-alt', name: 'CSS3', progress: '85%' },
      { icon: 'fab fa-js', name: 'JavaScript', progress: '80%' },
      { icon: 'fab fa-react', name: 'React.js', progress: '75%' }
    ],
    backend: [
      { icon: 'fab fa-node', name: 'Node.js', progress: '85%' },
      { icon: 'fas fa-server', name: 'Express.js', progress: '80%' },
      { icon: 'fas fa-database', name: 'MySQL', progress: '85%' },
      { icon: 'fas fa-leaf', name: 'MongoDB', progress: '75%' }
    ],
    languages: [
      { icon: 'fab fa-python', name: 'Python', progress: '90%' },
      { icon: 'fas fa-code', name: 'C', progress: '85%' },
      { icon: 'fab fa-cuttlefish', name: 'C++', progress: '80%' }
    ],
    tools: [
      { icon: 'fab fa-git-alt', name: 'Git & GitHub', progress: '85%' },
      { icon: 'fas fa-chart-bar', name: 'Power BI', progress: '80%' },
      { icon: 'fas fa-cloud-upload-alt', name: 'Netlify', progress: '85%' },
      { icon: 'fas fa-rocket', name: 'Render', progress: '75%' }
    ]
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: { staggerChildren: 0.15, delayChildren: 0.2 }
    }
  };

  const cardVariants = {
    hidden: { opacity: 0, y: 30, scale: 0.95 },
    visible: { opacity: 1, y: 0, scale: 1, transition: { type: 'spring', stiffness: 100 } }
  };

  const itemVariants = {
    hidden: { opacity: 0, x: -20 },
    visible: { opacity: 1, x: 0 }
  };

  return (
    <section id="skills" className="skills-unique">
      <div className="skills-bg-animation"></div>
      <div className="container">
        {/* Header with Tech Badge */}
        <motion.div
          className="skills-header-unique"
          initial={{ opacity: 0, y: -20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, amount: 0.2 }}
          transition={{ duration: 0.6 }}
        >
          <div className="tech-badge">
            <div className="badge-circuit">
              <div className="circuit-dot"></div>
              <div className="circuit-line"></div>
              <div className="circuit-dot"></div>
            </div>
            <span className="tech-badge-text">💻 Tech Arsenal</span>
          </div>
          <h2 className="skills-title-unique">
            <span className="title-skills">Skills</span>
            <span className="title-and">&</span>
            <span className="title-tech">Technologies</span>
          </h2>
          <p className="skills-subtitle-unique">My technical expertise across the full development spectrum</p>
        </motion.div>

        {/* Interactive Skills Dashboard */}
        <div className="skills-dashboard">
          <motion.div
            className="skills-categories-unique"
            variants={containerVariants}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, amount: 0.1 }}
          >

            {/* Frontend Category */}
            <motion.div
              className="skill-category-unique frontend-category"
              variants={cardVariants}
              whileHover={{ y: -5, boxShadow: "0 10px 30px rgba(99, 102, 241, 0.3)" }}
            >
              <div className="category-header">
                <div className="category-icon">
                  <i className="fas fa-palette"></i>
                </div>
                <div className="category-info">
                  <h3>Frontend</h3>
                  <span className="category-desc">User Interface & Experience</span>
                </div>
                <div className="skill-level">
                  <div className="level-ring">
                    <div className="level-fill" style={{ '--level': '85%' }}></div>
                    <span className="level-text">85%</span>
                  </div>
                </div>
              </div>
              <div className="skills-list">
                {skillsData.frontend.map((skill, index) => (
                  <motion.div key={index} className="skill-item" variants={itemVariants}>
                    <i className={skill.icon}></i>
                    <span>{skill.name}</span>
                    <div className="skill-bar">
                      <motion.div
                        className="skill-progress"
                        style={{ '--progress': skill.progress }}
                        initial={{ width: 0 }}
                        whileInView={{ width: skill.progress }}
                        viewport={{ once: true }}
                        transition={{ duration: 1, delay: 0.5 }}
                      ></motion.div>
                    </div>
                  </motion.div>
                ))}
              </div>
            </motion.div>

            {/* Backend Category */}
            <motion.div
              className="skill-category-unique backend-category"
              variants={cardVariants}
              whileHover={{ y: -5, boxShadow: "0 10px 30px rgba(16, 185, 129, 0.3)" }}
            >
              <div className="category-header">
                <div className="category-icon">
                  <i className="fas fa-server"></i>
                </div>
                <div className="category-info">
                  <h3>Backend</h3>
                  <span className="category-desc">Server & Database</span>
                </div>
                <div className="skill-level">
                  <div className="level-ring">
                    <div className="level-fill" style={{ '--level': '80%' }}></div>
                    <span className="level-text">80%</span>
                  </div>
                </div>
              </div>
              <div className="skills-list">
                {skillsData.backend.map((skill, index) => (
                  <motion.div key={index} className="skill-item" variants={itemVariants}>
                    <i className={skill.icon}></i>
                    <span>{skill.name}</span>
                    <div className="skill-bar">
                      <motion.div
                        className="skill-progress"
                        style={{ '--progress': skill.progress }}
                        initial={{ width: 0 }}
                        whileInView={{ width: skill.progress }}
                        viewport={{ once: true }}
                        transition={{ duration: 1, delay: 0.5 }}
                      ></motion.div>
                    </div>
                  </motion.div>
                ))}
              </div>
            </motion.div>

            {/* Languages Category */}
            <motion.div
              className="skill-category-unique languages-category"
              variants={cardVariants}
              whileHover={{ y: -5, boxShadow: "0 10px 30px rgba(245, 158, 11, 0.3)" }}
            >
              <div className="category-header">
                <div className="category-icon">
                  <i className="fas fa-code"></i>
                </div>
                <div className="category-info">
                  <h3>Languages</h3>
                  <span className="category-desc">Programming Languages</span>
                </div>
                <div className="skill-level">
                  <div className="level-ring">
                    <div className="level-fill" style={{ '--level': '88%' }}></div>
                    <span className="level-text">88%</span>
                  </div>
                </div>
              </div>
              <div className="skills-list">
                {skillsData.languages.map((skill, index) => (
                  <motion.div key={index} className="skill-item" variants={itemVariants}>
                    <i className={skill.icon}></i>
                    <span>{skill.name}</span>
                    <div className="skill-bar">
                      <motion.div
                        className="skill-progress"
                        style={{ '--progress': skill.progress }}
                        initial={{ width: 0 }}
                        whileInView={{ width: skill.progress }}
                        viewport={{ once: true }}
                        transition={{ duration: 1, delay: 0.5 }}
                      ></motion.div>
                    </div>
                  </motion.div>
                ))}
              </div>
            </motion.div>

            {/* Tools Category */}
            <motion.div
              className="skill-category-unique tools-category"
              variants={cardVariants}
              whileHover={{ y: -5, boxShadow: "0 10px 30px rgba(236, 72, 153, 0.3)" }}
            >
              <div className="category-header">
                <div className="category-icon">
                  <i className="fas fa-tools"></i>
                </div>
                <div className="category-info">
                  <h3>Tools & Deploy</h3>
                  <span className="category-desc">Development & Deployment</span>
                </div>
                <div className="skill-level">
                  <div className="level-ring">
                    <div className="level-fill" style={{ '--level': '82%' }}></div>
                    <span className="level-text">82%</span>
                  </div>
                </div>
              </div>
              <div className="skills-list">
                {skillsData.tools.map((skill, index) => (
                  <motion.div key={index} className="skill-item" variants={itemVariants}>
                    <i className={skill.icon}></i>
                    <span>{skill.name}</span>
                    <div className="skill-bar">
                      <motion.div
                        className="skill-progress"
                        style={{ '--progress': skill.progress }}
                        initial={{ width: 0 }}
                        whileInView={{ width: skill.progress }}
                        viewport={{ once: true }}
                        transition={{ duration: 1, delay: 0.5 }}
                      ></motion.div>
                    </div>
                  </motion.div>
                ))}
              </div>
            </motion.div>
          </motion.div>
        </div>
      </div>
    </section>
  );
};

export default Skills;
